<script setup lang="ts">
import { computed, reactive, ref } from 'vue';
import { router } from '@inertiajs/vue3';
import { route } from 'ziggy-js';
import AppLayout from '../../Layouts/AppLayout.vue';
defineOptions({ layout: AppLayout });
const props = defineProps<{ instrument: Record<string, any> | null; options: { factories: Array<{ id:number; name:string }>; departments:Array<{id:number;name:string;factory_id:number}>; types:Array<{id:number;name:string}>; brands:Array<{id:number;name:string}>; capacities:Array<{id:number;name:string}>; limits:Array<{id:number;name:string}>; specifications:Array<{id:number;name:string}> } }>();
const isEditing=!!props.instrument; const form=reactive<any>({code:props.instrument?.code??'',factory_id:props.instrument?.factory_id??'',department_id:props.instrument?.department_id??'',instrument_type_id:props.instrument?.instrument_type_id??'',brand_id:props.instrument?.brand_id??'',capacity_id:props.instrument?.capacity_id??'',acceptable_limit_id:props.instrument?.acceptable_limit_id??'',specification_id:props.instrument?.specification_id??'',notes:props.instrument?.notes??''}); const saving=ref(false); const confirmOpen=ref(false); const error=ref('');
const departments=computed(()=>form.factory_id?props.options.departments.filter(d=>d.factory_id===Number(form.factory_id)):props.options.departments); const isInactive=computed(()=>!!props.instrument&&(props.instrument.deleted_at!=null||props.instrument.is_active===false));
const submit=()=>{saving.value=true; const opts={onSuccess:()=>saving.value=false,onError:()=>{saving.value=false;error.value='Gagal menyimpan.'}}; isEditing?router.put(route('instruments.update',{instrument:props.instrument!.id}),form,opts):router.post(route('instruments.store'),form,opts)};
const remove=()=>{confirmOpen.value=false;router.delete(route('instruments.destroy',{instrument:props.instrument!.id}),{onError:()=>error.value='Gagal menonaktifkan.'})}; const activate=()=>router.post(route('instruments.activate',{instrument:props.instrument!.id}),{}, {onError:()=>error.value='Gagal mengaktifkan alat.'});
</script>
<template><div class="mx-auto max-w-2xl"><div class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div v-if="error" class="mb-4 rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">{{ error }}</div><div class="grid gap-4 sm:grid-cols-2"><label class="field-block sm:col-span-2"><span class="field-label">Kode Alat *</span><input v-model="form.code" class="control" placeholder="cth: W.FL.5"></label><label v-for="field in [{key:'factory_id',label:'Factory *',options:options.factories},{key:'department_id',label:'Departemen *',options:departments},{key:'instrument_type_id',label:'Jenis Alat *',options:options.types},{key:'brand_id',label:'Merk *',options:options.brands},{key:'capacity_id',label:'Kapasitas *',options:options.capacities},{key:'acceptable_limit_id',label:'Toleransi *',options:options.limits},{key:'specification_id',label:'Spesifikasi',options:options.specifications}]" :key="field.key" class="field-block"><span class="field-label">{{ field.label }}</span><select v-model="form[field.key]" class="control" @change="field.key === 'factory_id' && (form.department_id = '')"><option value="">{{ field.label }}</option><option v-for="option in field.options" :key="option.id" :value="option.id">{{ option.name }}</option></select></label><label class="field-block sm:col-span-2"><span class="field-label">Catatan</span><textarea v-model="form.notes" class="control min-h-24" /></label></div><div class="mt-6 space-y-2"><button class="secondary-button" :disabled="saving" @click="router.get(route('instruments.index'))">Batal</button><button v-if="isEditing && isInactive" class="success-button" @click="activate">Aktifkan Kembali</button><button v-else-if="isEditing" class="danger-button" @click="confirmOpen=true">Nonaktifkan Alat</button><button class="primary-button" :disabled="saving" @click="submit">{{ saving ? 'Menyimpan...' : isEditing ? 'Simpan Perubahan' : 'Simpan' }}</button></div></div><div v-if="confirmOpen" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/30 p-4"><div class="w-full max-w-sm rounded-xl bg-white p-5 shadow-xl"><h2 class="font-bold">Nonaktifkan Alat</h2><p class="mt-2 text-sm text-slate-500">Yakin ingin menonaktifkan alat “{{ form.code }}”?</p><div class="mt-5 flex justify-end gap-2"><button class="secondary-button" @click="confirmOpen=false">Batal</button><button class="danger-button" @click="remove">Ya, Nonaktifkan</button></div></div></div></div></template>
<style scoped>.field-block{display:flex;flex-direction:column;gap:.4rem}.field-label{font-size:.75rem;font-weight:600;color:#64748b}.control{width:100%;border:1px solid #cbd5e1;border-radius:.625rem;background:#fff;padding:.7rem .75rem;font-size:.875rem;outline:none}.control:focus{border-color:#fb923c;box-shadow:0 0 0 3px #fed7aa}.primary-button,.danger-button,.success-button,.secondary-button{width:100%;border-radius:.625rem;padding:.75rem 1rem;font-size:.875rem;font-weight:700}.primary-button{background:#f97316;color:#fff}.danger-button{background:#dc2626;color:#fff}.success-button{background:#16a34a;color:#fff}.secondary-button{border:1px solid #e2e8f0;background:#fff;color:#475569}</style>
